package com.praxbit.catalog;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ProductService {
    private final ProductRepository repository;

    public ProductService(ProductRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public ProductResponse find(long id) {
        Product product = repository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
        return new ProductResponse(product.getId(), product.getName(), product.getStock());
    }

    @Transactional
    public ProductResponse restock(long id, int amount) {
        Product product = repository.findById(id).orElseThrow(() -> new ProductNotFoundException(id));
        product.setStock(product.getStock() + amount);
        return new ProductResponse(product.getId(), product.getName(), product.getStock());
    }
}

record ProductResponse(long id, String name, int stock) {
}

class ProductNotFoundException extends RuntimeException {
    ProductNotFoundException(long id) {
        super("Product " + id + " was not found");
    }
}

interface ProductRepository extends JpaRepository<Product, Long> {
    List<Product> findByStockGreaterThan(int stock);
}

@Entity
class Product {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String name;
    private int stock;

    protected Product() {
    }

    Product(String name, int stock) {
        this.name = name;
        this.stock = stock;
    }

    Long getId() {
        return id;
    }

    String getName() {
        return name;
    }

    int getStock() {
        return stock;
    }

    void setStock(int stock) {
        this.stock = stock;
    }
}
